/* ============================================================================
   MarrowCounterSounds.js — the classic counter sound samples, base64-embedded.

   GENERATED — do not hand-edit the strings. These are the six MP3s the
   previous app (../Marrow/Marrow.js) streamed from diffpath.github.io, vendored
   here the only way audio can be: the app must work from file:// offline and
   make no outbound request from a screen with patient data on it, and fetch()
   of a local file is refused on file:// — so the bytes live in this script and
   are decoded in memory. ~150KB of text for ~110KB of audio.

   Regenerate by downloading the files and re-running the loop that built this:
     for f in Count-Click-High2 Count-Click-Med Count-Click-Low \
              Count-Click-Blast Complete-Nice 100-Soothing; do
         curl -sSfL -O "https://diffpath.github.io/media/$f.mp3"; done
   then base64 -w0 each into the matching key below.

   Consumed by MarrowCounter.js (counterSample), and OPTIONAL there: a template
   that does not load this file simply never offers the classic scheme.
   ========================================================================= */

const COUNTER_SAMPLES_B64 = {
    high: '',
    med: '',
    low: '',
    blast: '',
    hundred: '',
    complete: ''
};
